mapper.select:
SELECT c.*,( SELECT group_concat( s.store_name ) FROM member_store_info s WHERE s.store_id IN ( c.store_ids ) ) AS storeName,o.order_id FROM member_coupon_info c left join member_order_info o ON o.coupon_id=c.coupon_id WHERE c.deleted =0 and c.user_id=#{userId}
and c.status=#{status}
and c.room_type=#{roomType}
and #{storeId} in (c.store_ids)

select *
from member_coupon_info
where deleted = 0
  and user_id = #{userId}
  and coupon_id = #{couponId}

SELECT c.*,( SELECT group_concat( s.store_name ) FROM member_store_info s WHERE s.store_id IN ( c.store_ids ) ) AS storeName FROM member_coupon_info c WHERE c.deleted =0 and c.user_id is null and CONCAT(',', c.store_ids, ',') REGEXP #{storeIds}
and c.type=#{reqVO.type}
and #{reqVO.storeId} in (c.store_ids)
order by c.price asc
